// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    address owner;

    function setUp() public {
        c = new SimpleSuicide();
        owner = address(this); // deployer == owner per constructor
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(address(c), amount);
        uint256 ownerBefore = owner.balance;
        vm.prank(owner);
        c.sudicideAnyone();
        // Rule: the destroyed contract's funds land with the caller (the owner).
        assertTrue(address(c).balance == 0 && owner.balance == ownerBefore + amount);
    }
}
